    assert.deepEqual(result.answers, {
      "q-rate": { answer_type: "rating", value: 7 },
      "q-grateful": {
        answer_type: "text_list",
        value: ["my wife", "myself", "Flutter"],
      },
    });
    // 6 scripted model rounds at 1 input + 1 output token each (mock usage)
    assert.deepEqual(result.usage, { inputTokens: 6, outputTokens: 6 });
  });
});

