4	import { MockLanguageModelV4 } from "ai/test";
5	import type { QuestionSet, SessionClient } from "./session.ts";
6	import { runSession } from "./session.ts";
7	import { PROMPT_ID } from "./session-prompt.ts";
8	
9	const qRate = {
10	  id: "q-rate",
11	  text: "How would you rate your day?",
12	  answer_type: "rating",
13	} satisfies QuestionSet["questions"][number];
14	const qGrateful = {
15	  id: "q-grateful",
16	  text: "What are you grateful for?",
17	  answer_type: "text_list",
18	  min_answers: 3,
19	} satisfies QuestionSet["questions"][number];
20	const set: QuestionSet = {
21	  id: "test-set",
22	  name: "Test set",
23	  questions: [qRate, qGrateful],
24	};
25	
26	type MockContent =
27	  | { type: "text"; text: string }
28	  | { type: "tool-call"; toolCallId: string; toolName: string; input: string };
29	
30	// Scripted model: each doGenerate call shifts the next response off the queue.
31	function scriptedModel(script: MockContent[][]) {
32	  const queue = [...script];
33	  return new MockLanguageModelV4({
34	    doGenerate: async () => {
35	      const content = queue.shift();
36	      if (!content) throw new Error("mock model script exhausted");
37	      const isToolCall = content.some((c) => c.type === "tool-call");
38	      return {
39	        content,
40	        finishReason: {
41	          unified: isToolCall ? ("tool-calls" as const) : ("stop" as const),
42	          raw: undefined,
43	        },
44	        usage: {
45	          inputTokens: {
46	            total: 1,
47	            noCache: 1,
48	            cacheRead: undefined,
49	            cacheWrite: undefined,
50	          },
51	          outputTokens: { total: 1, text: 1, reasoning: undefined },
52	        },
53	        warnings: [],
54	      };
55	    },
56	  });
57	}
58	
59	const ask = (id: string, q: QuestionSet["questions"][number]): MockContent => ({
60	  type: "tool-call",
61	  toolCallId: id,
62	  toolName: "ask_question",
63	  input: JSON.stringify({
64	    question_id: q.id,
65	    question: q.text,
66	    answer_type: q.answer_type,
67	  }),
68	});
69	
70	const record = (
71	  id: string,
72	  questionId: string,
73	  answerType: string,
74	  value: unknown,
75	): MockContent => ({
76	  type: "tool-call",
77	  toolCallId: id,
78	  toolName: "record_answer",
79	  input: JSON.stringify({
80	    question_id: questionId,
81	    answer: { answer_type: answerType, value },
82	  }),
83	});
84	
85	const complete = (id: string, summary: string): MockContent => ({
86	  type: "tool-call",
87	  toolCallId: id,
88	  toolName: "complete_session",
89	  input: JSON.stringify({ summary }),
90	});
91	
92	describe("runSession", () => {
93	  it("rejects an answer below min_answers back to the model without storing it", async () => {
94	    const model = scriptedModel([
95	      [ask("c1", qGrateful)],
96	      [record("c2", "q-grateful", "text_list", ["just one", "and two"])],
97	      [complete("c3", "Gave up after the rejection.")],
98	      [{ type: "text", text: "Done." }],
99	    ]);
100	    const client: SessionClient = {
101	      askQuestion: async () => ["just one", "and two"],
102	    };
103	
104	    const result = await runSession({ questionSet: set, client, model });
105	
106	    assert.equal(result.answers["q-grateful"], undefined);
107	  });
108	
109	  it("halts with an error when the model never calls complete_session", async () => {
110	    // Model that asks the same question forever.
111	    const model = new MockLanguageModelV4({
112	      doGenerate: async () => ({
113	        content: [ask("loop", qRate)],
114	        finishReason: { unified: "tool-calls" as const, raw: undefined },
115	        usage: {
116	          inputTokens: {
117	            total: 1,
118	            noCache: 1,
119	            cacheRead: undefined,
120	            cacheWrite: undefined,
121	          },
122	          outputTokens: { total: 1, text: 1, reasoning: undefined },
123	        },
124	        warnings: [],
125	      }),
126	    });
127	    const client: SessionClient = { askQuestion: async () => 5 };
128	
129	    await assert.rejects(
130	      runSession({ questionSet: set, client, model }),
131	      /round limit/,
132	    );
133	  });
134	
135	  it("a repeated record_answer for the same question overwrites (last write wins)", async () => {
136	    const model = scriptedModel([
137	      [ask("c1", qRate)],
138	      [record("c2", "q-rate", "rating", 3)],
139	      [record("c3", "q-rate", "rating", 8)],
140	      [complete("c4", "Corrected the rating.")],
141	      [{ type: "text", text: "Done." }],
142	    ]);
143	    const client: SessionClient = { askQuestion: async () => 3 };
144	
145	    const result = await runSession({ questionSet: set, client, model });
146	
147	    assert.deepEqual(result.answers["q-rate"], {
148	      answer_type: "rating",
149	      value: 8,
150	    });
151	  });
152	
153	  it("walks the set in order and completes with a summary and validated answers", async () => {
154	    const model = scriptedModel([
155	      [ask("c1", qRate)],
156	      [record("c2", "q-rate", "rating", 7)],
157	      [ask("c3", qGrateful)],
158	      [
159	        record("c4", "q-grateful", "text_list", [
160	          "my wife",
161	          "myself",
162	          "Flutter",
163	        ]),
164	      ],
165	      [complete("c5", "A good day: rated 7, grateful for three things.")],
166	    ]);
167	
168	    const asked: AskQuestionInput[] = [];
169	    const client: SessionClient = {
170	      askQuestion: async (input) => {
171	        asked.push(input);
172	        return input.answer_type === "rating"
173	          ? 7
174	          : ["my wife", "myself", "Flutter"];
175	      },
176	    };
177	
178	    const result = await runSession({ questionSet: set, client, model });
179	
180	    assert.deepEqual(
181	      asked.map((a) => a.question_id),
182	      ["q-rate", "q-grateful"],
183	    );
184	    assert.equal(
185	      result.summary,
186	      "A good day: rated 7, grateful for three things.",
187	    );
188	    assert.deepEqual(result.answers, {
189	      "q-rate": { answer_type: "rating", value: 7 },
190	      "q-grateful": {
191	        answer_type: "text_list",
192	        value: ["my wife", "myself", "Flutter"],
193	      },
194	    });
195	    // 5 model rounds (ask, record, ask, record, complete) at 1+1 mock tokens
196	    assert.deepEqual(result.usage, { inputTokens: 5, outputTokens: 5 });
197	    // Full conversation is exposed for eval judging: initial user message,
198	    // model tool calls, and the client's tool results all present.
199	    assert.equal(result.messages[0]?.role, "user");
200	    const roles = result.messages.map((m) => m.role);
201	    assert.ok(roles.includes("assistant"));
202	    assert.ok(roles.includes("tool"));
203	    // Evals and PostHog events pin against the versioned prompt id.
204	    assert.equal(result.promptId, PROMPT_ID);
205	  });
206	});

