35	export type SessionClient = {
36	  /** Answer an ask_question tool call with the raw widget value. */
37	  askQuestion: (input: AskQuestionInput) => Promise<JSONValue>;
38	};
39	
40	export type SessionResult = {
41	  summary: string;
42	  answers: Record<string, Answer>;
43	  /** Token totals across every model round, for cost accounting. */
44	  usage: TokenUsage;
45	  /** The full conversation, for eval transcripts and debugging. */
46	  messages: ModelMessage[];
47	  /** Version id of the system prompt this session ran with. */
48	  promptId: string;
49	};
50	
51	// ponytail: generous cap — a poweruser recording 20 gratitudes must never hit
52	// it; tighten with real usage data once PostHog is wired (issue #5).
53	const MAX_ROUNDS_PER_QUESTION = 6;
54	const ROUND_SLACK = 20;
55	
56	function buildSessionTools(
57	  questionSet: QuestionSet,
58	  answers: SessionResult["answers"],
59	  onComplete: (summary: string) => void,
60	) {
61	  return {
62	    ask_question: tool({
63	      description:
64	        "Ask the user one journaling question; the client renders the widget.",
65	      inputSchema: askQuestionInput,
66	      // no execute: client-side tool — the session loop supplies the result
67	    }),
68	    record_answer: tool({
69	      description: "Record the validated answer for one question.",
70	      inputSchema: recordAnswerInput,
71	      execute: async ({ question_id, answer }) => {
72	        const question = questionSet.questions.find(
73	          (q) => q.id === question_id,
74	        );
75	        const min = question?.min_answers ?? 1;
76	        if (Array.isArray(answer.value) && answer.value.length < min) {
77	          return {
78	            recorded: false,
79	            error: `This question needs at least ${min} answers.`,
80	          };
81	        }
82	        answers[question_id] = answer;
83	        return { recorded: true };
84	      },
85	    }),
86	    complete_session: tool({
87	      description: "Finish the session with a summary of the journal entry.",
88	      inputSchema: completeSessionInput,
89	      execute: async ({ summary }) => {
90	        onComplete(summary);
91	        return { completed: true };
92	      },
93	    }),
94	  };
95	}
96	
97	export async function runSession(opts: {
98	  questionSet: QuestionSet;
99	  client: SessionClient;
100	  model: LanguageModel;
101	  /** Sampling temperature; evals pin 0 for stability, product uses default. */
102	  temperature?: number;
103	}): Promise<SessionResult> {
104	  const { questionSet, client, model, temperature } = opts;
105	  const answers: SessionResult["answers"] = {};
106	  const usage: TokenUsage = { inputTokens: 0, cacheReadTokens: 0, outputTokens: 0 };
107	  let summary: string | undefined;
108	
109	  const tools = buildSessionTools(questionSet, answers, (s) => {
110	    summary = s;
111	  });
112	
113	  const messages: ModelMessage[] = [
114	    { role: "user", content: "I am ready to start my journaling session." },
115	  ];
116	
117	  const maxRounds =
118	    questionSet.questions.length * MAX_ROUNDS_PER_QUESTION + ROUND_SLACK;
119	  let rounds = 0;
120	
121	  while (summary === undefined) {
122	    if (++rounds > maxRounds) {
123	      throw new Error(
124	        `Session round limit reached (${maxRounds}) without complete_session.`,
125	      );
126	    }
127	    const result = await generateText({
128	      model,
129	      instructions: sessionPrompt(questionSet),
130	      tools,
131	      stopWhen: isStepCount(1),
132	      temperature,
133	      messages,
134	    });
135	    messages.push(...result.response.messages);
136	    usage.inputTokens += result.usage.inputTokens ?? 0;
137	    usage.cacheReadTokens += result.usage.inputTokenDetails.cacheReadTokens ?? 0;
138	    usage.outputTokens += result.usage.outputTokens ?? 0;
139	
140	    if (result.finishReason !== "tool-calls") {
141	      continue;
142	    }
143	
144	    for (const call of result.toolCalls) {
145	      if (call.toolName !== "ask_question") {
146	        continue;
147	      }
148	      const value = await client.askQuestion(call.input as AskQuestionInput);
149	      messages.push({
150	        role: "tool",
151	        content: [
152	          {
153	            type: "tool-result",
154	            toolCallId: call.toolCallId,
155	            toolName: call.toolName,
156	            output: { type: "json", value: { answer: value } },
157	          },
158	        ],
159	      });
160	    }
161	  }
162	
163	  return { summary, answers, usage, messages, promptId: PROMPT_ID };
164	}

